cd /workspace && node -e "
const fs = require('fs');
const JSZip = require('jszip');

(async () => {
  const data = fs.readFileSync('testbed/docs/travel_summary.docx');
  const zip = await JSZip.loadAsync(data);
  let xml = await zip.file('word/document.xml').async('string');

  const note = 'These records reflect Maya Chen\\'s Seattle travel bookings as of September 2026. Please contact HR for any updates or corrections.';
  const newParagraph = '<w:p><w:r><w:t>' + note + '</w:t></w:r></w:p>';

  // Insert the new paragraph just before the closing </w:body> tag
  xml = xml.replace('</w:body>', newParagraph + '</w:body>');

  zip.file('word/document.xml', xml);
  const output = await zip.generateAsync({ type: 'nodebuffer' });
  fs.writeFileSync('testbed/docs/travel_summary.docx', output);
  console.log('Document updated successfully.');
})();
"

