cd /workspace && node -e "
const mammoth = require('mammoth');
const PDFDocument = require('pdfkit');
const fs = require('fs');

(async () => {
  const result = await mammoth.extractRawText({path: 'testbed/docs/travel_summary.docx'});
  const text = result.value;

  const doc = new PDFDocument({margin: 50, size: 'A4'});
  const stream = fs.createWriteStream('testbed/docs/travel_summary.pdf');
  doc.pipe(stream);

  const lines = text.split('\n');
  for (const line of lines) {
    if (line.trim() === '') {
      doc.moveDown(0.5);
    } else if (line === 'Travel Booking Summary') {
      doc.fontSize(18).font('Helvetica-Bold').text(line);
      doc.moveDown(0.5);
    } else if (['Flights', 'Hotels', 'Car Rentals'].includes(line.trim())) {
      doc.moveDown(0.3);
      doc.fontSize(14).font('Helvetica-Bold').text(line);
      doc.moveDown(0.3);
    } else if (line.startsWith('These records reflect')) {
      doc.moveDown(0.5);
      doc.fontSize(10).font('Helvetica-Oblique').text(line);
    } else {
      doc.fontSize(9).font('Helvetica').text(line);
    }
  }

  doc.end();
  stream.on('finish', () => {
    const stats = fs.statSync('testbed/docs/travel_summary.pdf');
    console.log('PDF created successfully: testbed/docs/travel_summary.pdf (' + (stats.size / 1024).toFixed(1) + ' KB)');
  });
})();
"
